window.acgolfPlantillasFR = [["Listo. Te hemos mandado un enlace nuevo a {E}. Mira también en «Correo no deseado».","C'est fait. Nous avons envoyé un nouveau lien à {E}. Regarde aussi dans « Courrier indésirable »."],
["Campo: {CAMPO}. Al crear la liga se elige entre tus campos favoritos o cualquiera del buscador de campos.","Parcours : {CAMPO}. À la création de la ligue, on choisit parmi tes parcours favoris ou n'importe lequel du moteur de recherche de parcours."],
["La liga se juega en {CAMPO}. Todas las partidas se apuntan en la app de la liga.","La ligue se joue à {CAMPO}. Toutes les parties se notent dans l'appli de la ligue."],
["La semana va de lunes a domingo. Cuentan todas las partidas de 18 hoyos jugadas esa semana en {CAMPO} y apuntadas en la app. Partida que no está en la app no cuenta, para nadie.","La semaine va du lundi au dimanche. Comptent toutes les parties de 18 trous jouées cette semaine à {CAMPO} et notées dans l'appli. Une partie qui n'est pas dans l'appli ne compte pas, pour personne."],
["Birdie, {n}. Tú hoy has desayunado bien, ¿eh?","Birdie, {n}. Tu as bien déjeuné ce matin, hein ?"],
["Bogey con tu golpe de regalo, {n}: par para ti. ¡Bien jugao!","Bogey avec ton coup de cadeau, {n} : c'est un par pour toi. Bien joué !"],
["Bogey, {n}. No pasa na, que esto es muy largo.","Bogey, {n}. Pas de souci, la partie est longue."],
["Bogey, {n}. Respira, que el siguiente es tuyo.","Bogey, {n}. Respire, le prochain est pour toi."],
["Bogey, {n}. Un golpito na más… y aquí no se dan bolas, ¿eh?","Bogey, {n}. Rien qu'un petit coup de trop… et ici, pas de putts offerts, hein ?"],
["Bogey. Tranquilo, {n}, que esto no es la tele: aquí se juega por las cañas.","Bogey. Tranquille, {n}, ce n'est pas la télé : ici, on joue pour les bières."],
["Bogey. {n}, ni tan mal: el próximo lo bordamos.","Bogey. {n}, pas si mal : le prochain, on le réussit."],
["Con tu golpe de ventaja, {n}, eso es un par. ¡Pa la saca!","Avec ton coup d'avance, {n}, c'est un par. Dans la poche !"],
["Doble bogey, {n}. Dicen que el golf es de caballeros… y de mucha paciencia.","Double bogey, {n}. On dit que le golf est un sport de gentlemen… et de grande patience."],
["Doble bogey. Tranquilo, {n}, que el campo también tiene derecho a ganar alguna.","Double bogey. Tranquille, {n}, le parcours a bien le droit d'en gagner une de temps en temps."],
["Doble bogey. {n}, ¿te cuento un secreto? En el hoyo siguiente nadie se acuerda.","Double bogey. {n}, je te dis un secret ? Au trou suivant, plus personne ne s'en souvient."],
["Doble bogey… {n}, ¿sabes por qué el golfista lleva dos pares de pantalones? ¡Por si hace un hoyo en uno! Venga, al siguiente.","Double bogey… {n}, sais-tu pourquoi le golfeur emporte deux pantalons ? Au cas où il ferait un trou en un ! Allez, au suivant."],
["Par, {n}. Así da gusto llevarte la bolsa.","Par, {n}. C'est un plaisir de porter ton sac."],
["Par, {n}. Más fiable que el reloj de la catedral.","Par, {n}. Plus fiable que l'horloge de la cathédrale."],
["Par, {n}. Sin aspavientos, como los buenos.","Par, {n}. Sans chichis, comme les bons."],
["Tranquilo, {n}: hasta el Seve hizo hoyos así. Bueno, el Seve no, pero su primo seguro.","Tranquille, {n} : même Seve a fait des trous comme ça. Bon, pas Seve, mais son cousin sûrement."],
["Uy, {n}… mi abuela decía: «el golf es un paseo estropeado». Hoy te ha tocado el trozo estropeado.","Aïe, {n}… ma grand-mère disait : « le golf, c'est une promenade gâchée ». Aujourd'hui, tu as eu le morceau gâché."],
["Uy, {n}… ¿cuántos han sido? Mejor no me lo digas, que me pongo malo.","Aïe, {n}… combien en as-tu fait ? Ne me le dis pas, j'en suis malade."],
["{n}, bogey con golpe: par neto. ¡Eso cuenta igual, mi arma!","{n}, bogey avec coup : par net. Ça compte pareil, mon ami !"],
["{n}, bogey. Con un putt menos era par: ¡que se lo digan al green!","{n}, bogey. Avec un putt de moins, c'était par : dis-le au green !"],
["{n}, bogey. El hoyo se ha llevado un golpito, nada más.","{n}, bogey. Le trou t'a pris un petit coup, rien de plus."],
["{n}, bogey. Tranquilo, quillo, que el hoyo también tiene su orgullo.","{n}, bogey. Tranquille, mon pote, le trou aussi a son orgueil."],
["{n}, con el golpe que te dan, es tu par. ¡Eso es saber jugar!","{n}, avec le coup qu'on te donne, c'est ton par. Ça, c'est savoir jouer !"],
["{n}, doble bogey. Esto en Sevilla lo llamamos «calentar motores».","{n}, double bogey. À Séville, on appelle ça « chauffer les moteurs »."],
["{n}, doble. Esa bola ha dado más vueltas que la noria de la feria.","{n}, double. Cette balle a fait plus de tours que le manège de la fête foraine."],
["{n}, doble. No se dan bolas, pero hoy te la daba yo de buena gana.","{n}, double. Pas de putts offerts, mais aujourd'hui je te l'offrirais volontiers."],
["{n}, doble. Si quieres te paso la toalla pa secarte las lágrimas.","{n}, double. Si tu veux, je te passe la serviette pour sécher tes larmes."],
["{n}, el hándicap está pa usarlo: par neto. ¡Olé!","{n}, le handicap est fait pour servir : par net. Olé !"],
["{n}, ese hoyo lo apuntamos con tinta invisible. ¡Al siguiente!","{n}, ce trou, on le note à l'encre invisible. Au suivant !"],
["{n}, ese hoyo se lo dejamos a los conejos. ¡Vámonos!","{n}, ce trou, on le laisse aux lapins. Allons-y !"],
["{n}, par. El campo ni se ha enterado de que has pasado.","{n}, par. Le parcours ne s'est même pas aperçu de ton passage."],
["{n}, par. Ni frío ni calor: ¡perfecto!","{n}, par. Ni chaud ni froid : parfait !"],
["{n}, tranquilo: el golf es como la vida, unos hoyos se ganan y otros se pagan.","{n}, tranquille : le golf, c'est comme la vie, certains trous se gagnent et d'autres se paient."],
["{n}, ¿has visto la bola por algún sitio? Yo tampoco. ¡Venga, borrón y cuenta nueva!","{n}, tu as vu la balle quelque part ? Moi non plus. Allez, on efface tout et on recommence !"],
["¡Arsa, arsa y arsa! Águila, {n}. Hoy no te tose nadie.","Waouh, waouh et waouh ! Eagle, {n}. Aujourd'hui, personne ne t'arrive à la cheville."],
["¡Arsa, birdie! {n}, hoy las cañas las pagas tú, que estás en racha.","Waouh, birdie ! {n}, aujourd'hui les bières, c'est toi qui les paies, tu es en feu."],
["¡Bien, {n}! Par. Así se juega, con la cabeza.","Bien, {n} ! Par. Voilà comment on joue, avec la tête."],
["¡Eso es, {n}! Par, y a otra cosa, mariposa.","C'est ça, {n} ! Par, et on passe à autre chose."],
["¡Mi arma, un ÁGUILA! {n}, eso hay que enmarcarlo y colgarlo en el bar.","Mon ami, un EAGLE ! {n}, ça mérite d'être encadré et accroché au bar."],
["¡Ole, ole y ole! Birdie, {n}. Así me gusta a mí.","Olé, olé et olé ! Birdie, {n}. C'est comme ça que je les aime."],
["¡Olé, {n}! Par de libro, sin despeinarte.","Olé, {n} ! Un par de manuel, sans te décoiffer."],
["¡Ozú, {n}! Un birdie como la Giralda de grande.","Ça alors, {n} ! Un birdie grand comme la Giralda."],
["¡Ozú, {n}! ¡Águila! Hoy te llevo la bolsa gratis, quillo.","Ça alors, {n} ! Eagle ! Aujourd'hui, je porte ton sac gratuitement, mon pote."],
["¡Pero qué me estás contando, {n}! ¡Birdie!","Mais qu'est-ce que tu me racontes, {n} ! Birdie !"],
["¡Que alguien llame a la tele! {n} ha hecho un águila.","Que quelqu'un appelle la télé ! {n} a fait un eagle."],
["¡Qué bueno eres, {n}! Par como un reloj.","Qu'est-ce que tu es bon, {n} ! Par réglé comme une horloge."],
["¡Te como los huevos, {n}! Birdie de categoría.","Chapeau, {n} ! Un birdie de classe."],
["¡Venga, {n}! Que hasta los profesionales tienen días así. Bueno, días no: hoyos.","Allez, {n} ! Même les pros ont des jours comme ça. Enfin, pas des jours : des trous."],
["¡{n}, birdie! Eso es de primera división, quillo.","{n}, birdie ! C'est de la première division, mon pote."],
["¡{n}, birdie! Eso no lo hace ni el Seve, mi arma.","{n}, birdie ! Même Seve ne ferait pas ça, mon ami."],
["¡{n}, águila! Ni en la Ryder se ve esto, mi arma.","{n}, eagle ! On ne voit même pas ça à la Ryder, mon ami."]];
